<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }

function kimpu_homepage_section_choices() {
    return array( 'about' => array( 'image-left' => __( 'Image Left / Content Right', 'kimpu-multipurpose' ), 'image-right' => __( 'Content Left / Image Right', 'kimpu-multipurpose' ), 'centered' => __( 'Centered', 'kimpu-multipurpose' ) ), 'services' => array( 'grid' => __( 'Service Grid', 'kimpu-multipurpose' ), 'featured' => __( 'Featured Service', 'kimpu-multipurpose' ) ), 'features' => array( 'three' => __( 'Three-column Grid', 'kimpu-multipurpose' ), 'four' => __( 'Four-column Grid', 'kimpu-multipurpose' ), 'split' => __( 'Split Content', 'kimpu-multipurpose' ) ), 'portfolio' => array( 'grid' => __( 'Standard Grid', 'kimpu-multipurpose' ), 'featured' => __( 'Large Featured Project', 'kimpu-multipurpose' ), 'editorial' => __( 'Editorial Portfolio', 'kimpu-multipurpose' ) ), 'statistics' => array( 'two' => __( 'Two Columns', 'kimpu-multipurpose' ), 'three' => __( 'Three Columns', 'kimpu-multipurpose' ), 'four' => __( 'Four Columns', 'kimpu-multipurpose' ) ), 'testimonials' => array( 'grid' => __( 'Accessible Grid', 'kimpu-multipurpose' ) ), 'team' => array( 'three' => __( 'Three Columns', 'kimpu-multipurpose' ), 'four' => __( 'Four Columns', 'kimpu-multipurpose' ), 'featured' => __( 'Featured Member', 'kimpu-multipurpose' ) ), 'faq' => array( 'accordion' => __( 'Native Accordion', 'kimpu-multipurpose' ) ), 'latest' => array( 'grid' => __( 'Article Grid', 'kimpu-multipurpose' ) ), 'cta' => array( 'centered' => __( 'Centered CTA', 'kimpu-multipurpose' ), 'split' => __( 'Split CTA', 'kimpu-multipurpose' ), 'banner' => __( 'Full-width Banner', 'kimpu-multipurpose' ) ), 'contact' => array( 'split' => __( 'Details and Content', 'kimpu-multipurpose' ), 'centered' => __( 'Centered Contact', 'kimpu-multipurpose' ) ) );
}

function kimpu_register_homepage_section_presentation( $c, $section, $choices ) {
    $section_id = 'kimpu_homepage_' . ( 'latest' === $section ? 'blog' : $section ); $prefix = 'kimpu_home_' . $section . '_'; $defaults = kimpu_homepage_section_defaults();
    kimpu_homepage_setting( $c, $prefix . 'enabled', $defaults[ $section ], 'rest_sanitize_boolean' ); kimpu_homepage_control( $c, $prefix . 'enabled', sprintf( __( 'Enable %s Section', 'kimpu-multipurpose' ), ucfirst( $section ) ), $section_id, 'checkbox' );
    kimpu_homepage_setting( $c, $prefix . 'title', '', 'sanitize_text_field' ); kimpu_homepage_control( $c, $prefix . 'title', __( 'Section Title', 'kimpu-multipurpose' ), $section_id );
    kimpu_homepage_setting( $c, $prefix . 'subtitle', '', 'sanitize_text_field' ); kimpu_homepage_control( $c, $prefix . 'subtitle', __( 'Subtitle', 'kimpu-multipurpose' ), $section_id );
    kimpu_homepage_setting( $c, $prefix . 'description', '', 'sanitize_textarea_field' ); kimpu_homepage_control( $c, $prefix . 'description', __( 'Description', 'kimpu-multipurpose' ), $section_id, 'textarea' );
    $fallback = array_key_first( $choices ); kimpu_homepage_setting( $c, $prefix . 'layout', $fallback, function( $v ) use ( $choices, $fallback ) { return array_key_exists( $v, $choices ) ? $v : $fallback; } ); kimpu_homepage_control( $c, $prefix . 'layout', __( 'Layout Variant', 'kimpu-multipurpose' ), $section_id, 'select', $choices );
    kimpu_homepage_setting( $c, $prefix . 'background', 'white', function( $v ) { return in_array( $v, array( 'white', 'muted', 'dark', 'primary' ), true ) ? $v : 'white'; } ); kimpu_homepage_control( $c, $prefix . 'background', __( 'Background Style', 'kimpu-multipurpose' ), $section_id, 'select', array( 'white' => __( 'White', 'kimpu-multipurpose' ), 'muted' => __( 'Muted', 'kimpu-multipurpose' ), 'dark' => __( 'Dark', 'kimpu-multipurpose' ), 'primary' => __( 'Primary', 'kimpu-multipurpose' ) ) );
    foreach ( array( 'background_color' => __( 'Background Color', 'kimpu-multipurpose' ), 'text_color' => __( 'Text Color', 'kimpu-multipurpose' ) ) as $key => $label ) { $id = $prefix . $key; kimpu_homepage_setting( $c, $id, '', 'sanitize_hex_color' ); $c->add_control( new WP_Customize_Color_Control( $c, $id, array( 'label' => $label, 'section' => $section_id ) ) ); }
    kimpu_homepage_setting( $c, $prefix . 'spacing', 'comfortable', function( $v ) { return in_array( $v, array( 'compact', 'comfortable', 'spacious' ), true ) ? $v : 'comfortable'; } ); kimpu_homepage_control( $c, $prefix . 'spacing', __( 'Section Spacing', 'kimpu-multipurpose' ), $section_id, 'select', array( 'compact' => __( 'Compact', 'kimpu-multipurpose' ), 'comfortable' => __( 'Comfortable', 'kimpu-multipurpose' ), 'spacious' => __( 'Spacious', 'kimpu-multipurpose' ) ) );
}

function kimpu_register_homepage_section_controls( $c ) {
    $choices = kimpu_homepage_section_choices(); $pages = kimpu_customizer_page_choices();
    foreach ( $choices as $section => $layout_choices ) { kimpu_register_homepage_section_presentation( $c, $section, $layout_choices ); }
    foreach ( array( 'kimpu_about_source_page' => __( 'About Content Source Page', 'kimpu-multipurpose' ), 'kimpu_services_source_page' => __( 'Services Parent Page', 'kimpu-multipurpose' ), 'kimpu_testimonials_source_page' => __( 'Testimonials Parent Page', 'kimpu-multipurpose' ), 'kimpu_team_source_page' => __( 'Team Parent Page', 'kimpu-multipurpose' ), 'kimpu_contact_source_page' => __( 'Contact Content Source Page', 'kimpu-multipurpose' ) ) as $id => $label ) { kimpu_homepage_setting( $c, $id, 0, 'absint' ); $section = false !== strpos( $id, 'about' ) ? 'kimpu_homepage_about' : ( false !== strpos( $id, 'services' ) ? 'kimpu_homepage_services' : ( false !== strpos( $id, 'testimonials' ) ? 'kimpu_homepage_testimonials' : ( false !== strpos( $id, 'team' ) ? 'kimpu_homepage_team' : 'kimpu_homepage_contact' ) ) ); kimpu_homepage_control( $c, $id, $label, $section, 'select', $pages ); }
    foreach ( array( 'kimpu_about_image' => array( __( 'About Featured Image', 'kimpu-multipurpose' ), 'kimpu_homepage_about' ), 'kimpu_cta_background_image' => array( __( 'CTA Background Image', 'kimpu-multipurpose' ), 'kimpu_homepage_cta' ) ) as $id => $data ) { kimpu_homepage_setting( $c, $id, 0, 'absint' ); $c->add_control( new WP_Customize_Media_Control( $c, $id, array( 'label' => $data[0], 'section' => $data[1], 'mime_type' => 'image' ) ) ); }
    $about = array( 'kimpu_about_image_alt' => array( __( 'About Image Alt Text', 'kimpu-multipurpose' ), 'sanitize_text_field' ), 'kimpu_about_cta_text' => array( __( 'About CTA Text', 'kimpu-multipurpose' ), 'sanitize_text_field' ), 'kimpu_about_cta_url' => array( __( 'About CTA URL', 'kimpu-multipurpose' ), 'esc_url_raw' ), 'kimpu_about_experience' => array( __( 'Experience Indicator', 'kimpu-multipurpose' ), 'sanitize_text_field' ) ); foreach ( $about as $id => $data ) { kimpu_homepage_setting( $c, $id, '', $data[1] ); kimpu_homepage_control( $c, $id, $data[0], 'kimpu_homepage_about', false !== strpos( $id, '_url' ) ? 'url' : 'text' ); }
    foreach ( array( 'kimpu_services_columns' => array( 3, array( 2 => '2', 3 => '3', 4 => '4' ) ), 'kimpu_services_limit' => array( 6, array( 0 => __( 'All', 'kimpu-multipurpose' ), 3 => '3', 6 => '6', 9 => '9' ) ) ) as $id => $data ) { kimpu_homepage_setting( $c, $id, $data[0], 'absint' ); kimpu_homepage_control( $c, $id, __( 'Services ' . ( false !== strpos( $id, 'columns' ) ? 'Columns' : 'Item Limit' ), 'kimpu-multipurpose' ), 'kimpu_homepage_services', 'select', $data[1] ); }
    kimpu_homepage_setting( $c, 'kimpu_features_items', '', 'sanitize_textarea_field' ); kimpu_homepage_control( $c, 'kimpu_features_items', __( 'Feature Items', 'kimpu-multipurpose' ), 'kimpu_homepage_features', 'textarea', array(), __( 'One per line: Title|Description|Icon. Icons are limited to the theme registry.', 'kimpu-multipurpose' ) );
    foreach ( array( 'kimpu_portfolio_limit' => array( 6, array( 0 => __( 'All', 'kimpu-multipurpose' ), 3 => '3', 6 => '6', 9 => '9' ) ), 'kimpu_portfolio_category' => array( 0, kimpu_customizer_category_choices() ) ) as $id => $data ) { kimpu_homepage_setting( $c, $id, $data[0], 'absint' ); kimpu_homepage_control( $c, $id, false !== strpos( $id, 'category' ) ? __( 'Project Category', 'kimpu-multipurpose' ) : __( 'Project Item Limit', 'kimpu-multipurpose' ), 'kimpu_homepage_portfolio', 'select', $data[1] ); }
    kimpu_homepage_setting( $c, 'kimpu_statistics_items', '', 'sanitize_textarea_field' ); kimpu_homepage_control( $c, 'kimpu_statistics_items', __( 'Statistics Items', 'kimpu-multipurpose' ), 'kimpu_homepage_statistics', 'textarea', array(), __( 'One per line: Label|Value|Prefix|Suffix.', 'kimpu-multipurpose' ) );
    kimpu_homepage_setting( $c, 'kimpu_faq_items', '', 'sanitize_textarea_field' ); kimpu_homepage_control( $c, 'kimpu_faq_items', __( 'FAQ Items', 'kimpu-multipurpose' ), 'kimpu_homepage_faq', 'textarea', array(), __( 'One per line: Question|Answer.', 'kimpu-multipurpose' ) ); kimpu_homepage_setting( $c, 'kimpu_faq_single_open', false, 'rest_sanitize_boolean' ); kimpu_homepage_control( $c, 'kimpu_faq_single_open', __( 'Allow Only One FAQ Open', 'kimpu-multipurpose' ), 'kimpu_homepage_faq', 'checkbox' );
    /* Blog Settings owns shared columns and card metadata so the homepage and blog archive stay consistent without duplicate setting IDs. */
    kimpu_homepage_setting( $c, 'kimpu_blog_count', 3, 'absint' ); kimpu_homepage_control( $c, 'kimpu_blog_count', __( 'Homepage Post Count', 'kimpu-multipurpose' ), 'kimpu_homepage_blog', 'select', array( 3 => '3', 6 => '6', 9 => '9' ) );
    $cta = array( 'kimpu_cta_headline' => array( __( 'Headline', 'kimpu-multipurpose' ), 'sanitize_text_field' ), 'kimpu_cta_description' => array( __( 'Description', 'kimpu-multipurpose' ), 'sanitize_textarea_field' ), 'kimpu_cta_primary_text' => array( __( 'Primary Button Text', 'kimpu-multipurpose' ), 'sanitize_text_field' ), 'kimpu_cta_primary_url' => array( __( 'Primary Button URL', 'kimpu-multipurpose' ), 'esc_url_raw' ), 'kimpu_cta_secondary_text' => array( __( 'Secondary Button Text', 'kimpu-multipurpose' ), 'sanitize_text_field' ), 'kimpu_cta_secondary_url' => array( __( 'Secondary Button URL', 'kimpu-multipurpose' ), 'esc_url_raw' ) ); foreach ( $cta as $id => $data ) { kimpu_homepage_setting( $c, $id, '', $data[1] ); kimpu_homepage_control( $c, $id, $data[0], 'kimpu_homepage_cta', false !== strpos( $id, '_url' ) ? 'url' : ( false !== strpos( $id, 'description' ) ? 'textarea' : 'text' ) ); }
    foreach ( array( 'kimpu_contact_email' => array( __( 'Email', 'kimpu-multipurpose' ), 'sanitize_email' ), 'kimpu_contact_phone' => array( __( 'Phone', 'kimpu-multipurpose' ), 'sanitize_text_field' ), 'kimpu_contact_address' => array( __( 'Address', 'kimpu-multipurpose' ), 'sanitize_text_field' ), 'kimpu_contact_hours' => array( __( 'Working Hours', 'kimpu-multipurpose' ), 'sanitize_text_field' ), 'kimpu_contact_map_url' => array( __( 'Map Link', 'kimpu-multipurpose' ), 'esc_url_raw' ) ) as $id => $data ) { kimpu_homepage_setting( $c, $id, '', $data[1] ); kimpu_homepage_control( $c, $id, $data[0], 'kimpu_homepage_contact', false !== strpos( $id, '_url' ) ? 'url' : 'text' ); }
}
